SELECT PRO.CODPROD,
	PRO.DESCRPROD,
	PRO.CODVOL,
	NVL(SUM(EST.ESTOQUE),0) AS ESTOQUE,
	(SELECT NVL(SUM(ITE.QTDNEG),0) FROM TGFITE ITE INNER JOIN TGFCAB CAB ON ITE.NUNOTA = CAB.NUNOTA WHERE CAB.TIPMOV IN ('Q', 'T') AND ITE.CODLOCALORIG = 101 AND ITE.ATUALESTOQUE = -1 AND (EXTRACT(MONTH FROM CAB.DTENTSAI) = EXTRACT(MONTH FROM ADD_MONTHS(SYSDATE, -1))) AND EXTRACT(YEAR FROM CAB.DTENTSAI) = EXTRACT(YEAR FROM ADD_MONTHS(SYSDATE, -1)) AND ITE.CODPROD = PRO.CODPROD) AS ANTERIOR1,
	(SELECT NVL(SUM(ITE.QTDNEG),0) FROM TGFITE ITE INNER JOIN TGFCAB CAB ON ITE.NUNOTA = CAB.NUNOTA WHERE CAB.TIPMOV IN ('Q', 'T') AND ITE.CODLOCALORIG = 101 AND ITE.ATUALESTOQUE = -1 AND (EXTRACT(MONTH FROM CAB.DTENTSAI) = EXTRACT(MONTH FROM ADD_MONTHS(SYSDATE, -2))) AND EXTRACT(YEAR FROM CAB.DTENTSAI) = EXTRACT(YEAR FROM ADD_MONTHS(SYSDATE, -2)) AND ITE.CODPROD = PRO.CODPROD) AS ANTERIOR2,
	(SELECT NVL(SUM(ITE.QTDNEG),0) FROM TGFITE ITE INNER JOIN TGFCAB CAB ON ITE.NUNOTA = CAB.NUNOTA WHERE CAB.TIPMOV IN ('Q', 'T') AND ITE.CODLOCALORIG = 101 AND ITE.ATUALESTOQUE = -1 AND (EXTRACT(MONTH FROM CAB.DTENTSAI) = EXTRACT(MONTH FROM ADD_MONTHS(SYSDATE, -3))) AND EXTRACT(YEAR FROM CAB.DTENTSAI) = EXTRACT(YEAR FROM ADD_MONTHS(SYSDATE, -3)) AND ITE.CODPROD = PRO.CODPROD) AS ANTERIOR3,
	(SELECT NVL(SUM(ITE.QTDNEG),0) FROM TGFITE ITE INNER JOIN TGFCAB CAB ON ITE.NUNOTA = CAB.NUNOTA WHERE CAB.TIPMOV IN ('Q', 'T') AND ITE.CODLOCALORIG = 101 AND ITE.ATUALESTOQUE = -1 AND (EXTRACT(MONTH FROM CAB.DTENTSAI) = EXTRACT(MONTH FROM ADD_MONTHS(SYSDATE, -4))) AND EXTRACT(YEAR FROM CAB.DTENTSAI) = EXTRACT(YEAR FROM ADD_MONTHS(SYSDATE, -4)) AND ITE.CODPROD = PRO.CODPROD) AS ANTERIOR4,
	(SELECT NVL(SUM(ITE.QTDNEG),0) FROM TGFITE ITE INNER JOIN TGFCAB CAB ON ITE.NUNOTA = CAB.NUNOTA WHERE CAB.TIPMOV IN ('Q', 'T') AND ITE.CODLOCALORIG = 101 AND ITE.ATUALESTOQUE = -1 AND (EXTRACT(MONTH FROM CAB.DTENTSAI) = EXTRACT(MONTH FROM ADD_MONTHS(SYSDATE, -5))) AND EXTRACT(YEAR FROM CAB.DTENTSAI) = EXTRACT(YEAR FROM ADD_MONTHS(SYSDATE, -5)) AND ITE.CODPROD = PRO.CODPROD) AS ANTERIOR5,
	(SELECT NVL(SUM(ITE.QTDNEG),0) FROM TGFITE ITE INNER JOIN TGFCAB CAB ON ITE.NUNOTA = CAB.NUNOTA WHERE CAB.TIPMOV IN ('Q', 'T') AND ITE.CODLOCALORIG = 101 AND ITE.ATUALESTOQUE = -1 AND (EXTRACT(MONTH FROM CAB.DTENTSAI) = EXTRACT(MONTH FROM ADD_MONTHS(SYSDATE, -6))) AND EXTRACT(YEAR FROM CAB.DTENTSAI) = EXTRACT(YEAR FROM ADD_MONTHS(SYSDATE, -6)) AND ITE.CODPROD = PRO.CODPROD) AS ANTERIOR6,
	NVL(PRO.ESTMIN,0) AS ESTMIN,
	--(SELECT MAX(Ca.DTENTSAI) FROM TGFCAB Ca INNER JOIN TGFITE It ON Ca.NUNOTA = It.NUNOTA WHERE It.CODPROD = PRO.CODPROD AND Ca.TIPMOV = 'C') AS ULTCOMPRA,
	(SELECT NVL(SUM(I.QTDNEG),0) FROM TGFITE I INNER JOIN TGFCAB C ON I.NUNOTA = C.NUNOTA WHERE C.CODTIPOPER IN (SELECT DISTINCT T.CODTIPOPER FROM TGFTOP T WHERE T.GRUPO = 'Pedido Compra') AND C.STATUSNOTA = 'L' AND I.PENDENTE = 'S' AND I.CODPROD = PRO.CODPROD) AS COMPRA
FROM TGFPRO PRO
	INNER JOIN TGFEST EST ON PRO.CODPROD = EST.CODPROD
WHERE EST.CODLOCAL = 101
	AND SUBSTR(PRO.CODPROD,1,1) <> 3
	AND ((:P_CODGRUPOPROD IS NULL) OR (PRO.CODGRUPOPROD = :P_CODGRUPOPROD))
	AND ((:P_CODPROD IS NULL) OR (PRO.CODPROD = :P_CODPROD))
GROUP BY PRO.CODPROD,
	PRO.DESCRPROD,
	PRO.CODVOL,
	NVL(PRO.ESTMIN,0)
ORDER BY PRO.CODPROD
